mapper.select:
SELECT
,T2.CASH_TYPE_2 FROM FIN_CASH_PLAN T1, FIN_CASH_INFO T2 WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
ORDER BY T1.VDATE ASC

SELECT
, CASE WHEN COUNT(T3.CASH_ID) > 0 THEN 'Y' ELSE 'N' END isPayed FROM FIN_CASH_INFO T2, FIN_CASH_PLAN T1 LEFT JOIN TRD_PRODUCT_DEAL T3 ON T1.CASH_ID = T3.CASH_ID and T3.MDATE = T1.MDATE and T3.TRADE_STATUS = '01' and T3.IS_CANCEL = 'N' WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
GROUP BY T1.CASH_ID, T1.MDATE, T1.CASH_NUM, T1.CASH_TYPE, T1.VDATE_UNADJUST, T1.MDATE_UNADJUST, T1.PAY_DATE_UNADJUST, T1.VDATE, T1.PAY_DATE, T1.TERMDAYS, T1.VDATE_Y, T1.VDATE_TERM, T1.MDATE_TERM, T1.TERMDAYS_TERM, T1.PRIN_AMT, T1.INT_PRIN_AMT, T1.INT_AMT, T1.IS_PAY_INT, T1.CASH_AMT, T1.CASH_BASEAMT, T1.CASH_UNIT_TYPE, T1.CALC_FUNCTION, T1.FREQUENCY, T1.FINPROD_ID, T1.FINPROD_TYPE, T1.FINPROD_TYPE2, T1.BRANCH, T1.PAY_TYPE, T1.RANGE_YIELD, T1.CREATE_USER, T1.CREATE_DEPT, T1.CREATE_TIME, T1.UPDATE_USER, T1.UPDATE_TIME
